// CP99 - Reports page "Print PDF": same PTC-branded US Letter template as the other CLMS PDFs (pdfHeader.js header, shared table CSS,
// footer, and the CP97/CP143 "Generated By" line + signature). It prints exactly what the report table holds: every row that matches the current
// search (not just the visible page), with the same columns and cell wording as the on-screen table.
import { buildPdfDocumentHtml, pdfCommonCss } from './pdfHeader.js';
import { generatedStamp } from './laboratoriesPdf.js';
import { formatReportValue, displayReportColumn } from './reportFormatting.mjs';

const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

/** @param {string} title report title shown on screen  @param {string[]} columns column keys  @param {object[]} rows view rows already filtered by search */
export function buildReportsPdfHtml(title, columns, rows, { search = '', logoBase = '', now = new Date() } = {}) {
  const stamp = generatedStamp(now);
  const head = columns.map(c => `<th>${esc(displayReportColumn(c))}</th>`).join('');
  const body = rows.length
    ? rows.map(r => `<tr>${columns.map(c => `<td>${esc(formatReportValue(r[c]))}</td>`).join('')}</tr>`).join('')
    : `<tr><td colspan="${Math.max(columns.length, 1)}" class="pdf-empty">No records match your search.</td></tr>`;
  const html = buildPdfDocumentHtml({
    title: `CLMS ${title}`, logoBase, signature: true,
    bodyHtml: `<h2 class="pdf-title">${esc(String(title).toUpperCase())}</h2>
<p class="pdf-meta">Total records: ${rows.length}${search ? ` &nbsp;|&nbsp; Search filter: “${esc(search)}”` : ''} &nbsp;|&nbsp; Generated: ${esc(stamp)}</p>
<table class="pdf-table"><thead><tr>${head}</tr></thead><tbody>${body}</tbody></table>`,
  });
  // Wide reports (many columns) shrink the table text a little so they still fit the Letter width; narrower ones use the shared size.
  const dense = columns.length > 8 ? '.pdf-table th,.pdf-table td{font-size:6.5pt}' : '';
  return html.replace('</style>', `${pdfCommonCss(stamp)}${dense}</style>`);
}
